  "code": "from flask import Flask, request, redirect
import base64
import os

app = Flask(__name__)

@app.route('/img/upload', methods=['POST'])
def upload_img():
    '''
    Get image file from request and save it to ./pictures folder after encoding
    '''
    if 'file' not in request.files:
        return redirect(request.url)
    file = request.files['file']
    if file.filename == '':
        return redirect(request.url)
    if file:
        img_data = file.read()
        encoded_img = base64.b64encode(img_data).decode('utf-8')
        if not os.path.exists('./pictures'):
            os.makedirs('./pictures')
        with open('./pictures/' + file.filename, 'wb') as f:
            f.write(base64.b64decode(encoded_img))
        return 'File successfully uploaded and saved as ' + file.filename
